package vn.hust.restaurant.controller;import java.sql.*;import vn.hust.restaurant.model.UserSession;import vn.hust.restaurant.service.AuthService;public class AuthController{private final AuthService s;public AuthController(AuthService s){this.s=s;}public UserSession login(String u,char[]p)throws SQLException{return s.login(u,p);}public String requestOtp(String i)throws Exception{return s.requestOtp(i);}public void reset(String o,String p)throws SQLException{s.resetPassword(o,p);}}